import { ProfileGateway } from '../services/ProfileGateway'
@Component
export struct ProfileEditor {
  @State displayName: string = ''
  private gateway: ProfileGateway = new ProfileGateway()
  saveProfile(): void {
    if (this.displayName.trim().length === 0) {
      promptAction.showToast({ message: 'Display name is required' })
      return
    }
    this.gateway.updateProfile(this.displayName)
  }
  build() {}
}

