export class PurchaseCoordinator {
  customerCode: string = ''
  commitPurchase(): void {
    if (this.customerCode.trim().length === 0) {
      promptAction.showToast({ message: 'Customer code is required' })
      return
    }
    purchaseClient.placeOrder(this.customerCode)
    AppStorage.SetOrCreate('lastPurchaseCustomer', this.customerCode)
  }
}

